 function battleTransforms(m){if(!game.battle)return'';const options=transformationOptions(game,dex,m);return '<section class="pk-battle-powers" aria-label="'+t('พลังพิเศษ','Special powers')+'"><header><strong>'+t('พลังพิเศษ','Special power')+'</strong><span>'+t('เลือกแล้วกดท่า','Choose, then use a move')+'</span></header><div>'+options.map(v=>button(esc(v.label),'battle-power','data-kind="'+v.kind+'" data-key="'+esc(v.key)+'" aria-pressed="'+(pendingTransform?.kind===v.kind&&pendingTransform?.key===v.key)+'"'+(!v.ready?' disabled':'')+' title="'+esc(v.reason||v.item||v.label)+'"','pk-power-option')).join('')+'</div>'+(pendingTransform?'<p class="pk-form-note">'+esc(pendingTransform.label)+' · '+t('จะทำงานพร้อมท่าถัดไป','Activates with your next move')+'</p>':options.some(v=>v.reason.startsWith('Requires'))?'<p class="pk-muted">'+t('ต้องมีอุปกรณ์ตามเงื่อนไข · ปรับได้ใน ตั้งค่า → การแปลงร่าง','Equipment required. Configure in Settings → Transformations.')+'</p>':'')+'</section>';}
