   const rows=game.party.map(uid=>{const b=base.mons[uid],m=game.pokemon[uid];if(!m)return null;const gained=b?Math.max(0,(m.exp||0)-b.exp):0,levels=b?m.level-b.level:0,learned=b?(m.moves||[]).map(v=>v.id).filter(id=>!b.moves.includes(id)).map(id=>dex.moves?.[id]?.name||title(String(id))):[];return {uid,name:monName(m),key:m.key,level:m.level,gained,levels,learned,fainted:!m.hp};}).filter(Boolean);
