 async function apply(input){if(motion.playing())throw Error(t('รอแอนิเมชันจบก่อน','Wait for the animation to finish'));if(mutating||working||busy())throw Error(t('รอการกระทำก่อนหน้าให้เสร็จ','Wait for the current action to finish'));if(!enabled()||!scope)throw Error(t('เปิด Addon ในแชทนี้ก่อน','Enable this addon in the current chat'));refresh();if(input.type==='settings'&&(input.autoNarrate!==undefined||input.terrain!==undefined)&&api.savePokemonConfiguration){const ticket=context();mutating=true;try{await api.savePokemonConfiguration({...typeof input.autoNarrate==='boolean'?{autoNarrate:input.autoNarrate}:{},...input.terrain!==undefined?{terrain:input.terrain}:{}});assertScope(ticket);}finally{mutating=false;refresh();}return;}const beforeGame=game;const c=cHost(),ticket=context(),rows=c.chat,message=rows.filter(m=>!m.is_user&&!m.is_system).at(-1);if(!message)throw Error('Start the chat first');const imported=input.type==='import-item',beforeState=context().state;let nextState;if(imported){const legacy=beforeState.inventory?.find(i=>i.id===input.sourceId),known=resolveRoleItem(dex,legacy);if(!legacy||legacy.quantity<=0||legacy.commerceRightId||known?.id!==input.item)throw Error('This inventory item cannot be imported');nextState=structuredClone(beforeState);nextState.inventory=nextState.inventory.filter(i=>i.id!==legacy.id);input={type:'grant-item',source:'import',item:known.id,quantity:legacy.quantity,sourceId:legacy.id};}const event=journalEvent({...input,engine:4,context:{place:context().state?.location?.place||'',time:context().state?.worldClock?.time||'',weather:context().state?.weather||context().state?.worldClock?.weather||''},id:newActionId()},message);const after=transition(game,event,dex,rules()),purseState=context().state,purse=purseState?.progression?.currency,change=imported?null:walletChange(game,after,event,purse?walletBalance(purse):0);let paid=null;if(change){paid=purse?changeWallet(purseState,change.delta):null;if(!paid&&['shop-buy','shop-sell'].includes(event.type))throw Error(purse?'Not enough money':'This chat has no wallet');}const previous=message.extra,extra={...previous,[JOURNAL]:[...previous?.[JOURNAL]||[],event]};assertScope(ticket);mutating=true;message.extra=extra;try{if(imported){const saved=await api.commitState(nextState,'pokemon-inventory',{saveMetadataOverride:savePokemonChat});if(!saved)throw Error('Inventory import was not saved');}else if(paid){const saved=await api.commitState(paid,'pokemon-wallet',{txn:change.txn,reason:walletReason(change,event,after),saveMetadataOverride:savePokemonChat});if(!saved)throw Error('Pokémon progress could not be saved. Check the connection and retry.');}else await savePokemonChat(c);assertScope(ticket);pendingNarration=true;cacheStamp='';notice='';refresh();}catch(error){if(message.extra===extra)message.extra=previous;cacheStamp='';refresh();throw error;}finally{mutating=false;}api.refreshHost?.();presentNewBattle(beforeGame);playMotion(motionSequence(beforeGame,game,event,dex),beforeGame.battle?beforeGame:game);if(['evolve','trade-evolve'].includes(event.type)){const uid=event.uid||Object.keys(game.pokemon).find(id=>beforeGame.pokemon?.[id]&&beforeGame.pokemon[id].key!==game.pokemon[id].key);if(uid&&beforeGame.pokemon?.[uid]&&beforeGame.pokemon[uid].key!==game.pokemon[uid]?.key)playEvolution(beforeGame.pokemon[uid],game.pokemon[uid]);}if(game.settings.autoNarrate&&!['settings','narrated','shop-buy','shop-sell','transformation-settings','pokemon-form-settings','preset-save','preset-delete'].includes(input.type))void narrate().catch(showError);return event;}
 async function saveSpriteStyle(value){if(mutating||working||busy())return;const ticket=context();mutating=true;render();try{await api.savePokemonConfiguration({spriteStyle:value});assertScope(ticket);}finally{mutating=false;failedSprites.clear();refresh();}}
 function walletReason(change,event,after){const item=event.item?itemName(dex,event.item)+' ×'+event.quantity:'',who=[after.lastBattle?.trainer,after.lastBattle?.partnerTrainer].filter(Boolean).join(' & ');return ({buy:'Poké Mart · '+item,sell:'Poké Mart sale · '+item,prize:'Prize money · '+who,penalty:'Lost battle · '+who})[change.kind]||'Pokémon';}
 function assertScope(ticket){const c=context();if(!enabled()||c.key!==ticket.key||c.nonce!==ticket.nonce)throw Error(t('เปลี่ยนแชทระหว่างบันทึก','Chat changed during the action'));}
 const errorThai={'Not enough money':'เงินไม่พอ','This chat has no wallet':'แชทนี้ยังไม่มีกระเป๋าเงิน','Shops are closed during battle':'ร้านปิดระหว่างการต่อสู้','The shop is turned off':'ร้านค้าปิดอยู่ในตั้งค่า','This item is not sold here':'ร้านนี้ไม่ได้ขายของชิ้นนี้','Not enough items to sell':'มีของไม่พอจะขาย','This item cannot be sold':'ของชิ้นนี้ขายไม่ได้','Selling is turned off':'ปิดการขายไว้ในตั้งค่า','Item stock limit reached':'กระเป๋าเต็ม','Pokémon progress could not be saved. Check the connection and retry.':'บันทึก Pokémon ไม่สำเร็จ ตรวจการเชื่อมต่อแล้วลองใหม่','Chat integrity check failed. Reload before retrying; no overwrite was requested.':'ตรวจสอบไฟล์แชทไม่ผ่าน โหลดหน้าใหม่ก่อนลองอีกครั้ง ระบบไม่ได้เขียนทับไฟล์','This item would have no effect; nothing was consumed':'ไอเทมนี้ไม่มีผลกับเป้าหมาย จึงไม่หักจำนวน','Visit a Pokémon Center in the story first':'ไปถึง Pokémon Center ในโรลก่อนรับบริการ','Visit this Gym in the story first':'ไปถึงยิมนี้ในโรลก่อนท้าสู้','The compatible TM is not in your bag':'ยังไม่มี TM ที่ตรงกับท่านี้ในกระเป๋า','This Pokémon cannot learn that move here':'โปเกมอนตัวนี้ยังเรียนท่านี้ไม่ได้','Finish the battle before changing moves':'จบการต่อสู้ก่อนเปลี่ยนท่า','Visit a Move Tutor or Pokémon Center':'ไปพบผู้ฝึกท่าหรือ Pokémon Center ก่อน','Enable Sandbox yourself before using cheats':'เปิด Sandbox ด้วยตัวเองก่อนใช้คำสั่งโกง','Finish the encounter before editing the world':'จบการต่อสู้ก่อนแก้ไขข้อมูล','IV must be an integer from 0 to 31':'IV ต้องเป็นจำนวนเต็ม 0–31','EV must be 0–252 per stat and at most 510 total':'EV ต้องอยู่ที่ 0–252 ต่อค่า และรวมไม่เกิน 510','Only wild Pokémon can be caught':'จับได้เฉพาะโปเกมอนป่าเท่านั้น','A fainted Pokémon needs Revive or a Pokémon Center':'ตัวที่หมดสภาพต้องใช้ Revive หรือรักษาที่ Pokémon Center','Choose a fainted Pokémon':'เลือกตัวที่หมดสภาพก่อน','Leave the Center or Gym before exploring for wild Pokémon':'ออกจากศูนย์หรือยิมก่อนสำรวจหาโปเกมอนป่า','Choose a permanent base form; use Fight → Special power for battle transformations':'เลือกฟอร์มฐานถาวร แล้วใช้ ต่อสู้ → พลังพิเศษ เพื่อแปลงร่าง','Accept the quest and reach its destination first':'รับภารกิจและไปถึงจุดหมายก่อน','This rare encounter has already been completed':'ภารกิจพบตัวนี้สำเร็จไปแล้ว','Stat overrides must be 1–99999 or blank':'ค่าสเตตัสกำหนดเองต้องเป็น 1–99999 หรือเว้นว่าง'};
 function showError(error){const message=String(error.message||error);notice=t(errorThai[message]||message,message);render();}
 async function narrate(){if(working||busy())throw Error(t('AI กำลังตอบอยู่','AI is already generating'));assertScope(context());refresh();const c=cHost(),ticket=context(),rows=c.chat,last=rows.at(-1),beforeText=String(last?.mes||'');let completed=false;if(!last||last.is_user||last.is_system)throw Error(t('รอให้ AI ตอบก่อน แล้วกดบรรยายต่อ','Wait for an assistant reply before continuing'));const restoreDraft=preserveDraft(document,context);working=true;render();const clear=()=>c.setExtensionPrompt(ACTION_PROMPT,'',1,0,false,0);const changed=()=>clear();c.eventSource.on(c.eventTypes.CHAT_CHANGED,changed);const ended=['victory','trainer-victory','defeat','run','caught'].includes(game.lastResult?.key)&&!game.battle;c.setExtensionPrompt(ACTION_PROMPT,'Continue this assistant message from where it ends, using the resolved Pokémon events below. Write ONLY the new continuation: never restate, rewrite or summarise the earlier text of this message. '+JSON.stringify({results:game.logs.slice(-12),...ended?{finishedBattle:game.lastBattle}:{}})+' Narrate the consequences, including any fainted Pokémon being returned to its Poké Ball; do not speak for the player and do not repeat the mechanical action or add rewards. Leave the next choice to the player.',1,0,false,0);const guard=guardContinuation(c,last);try{await c.generate('continue',{automatic_trigger:true,depth:1});guard.repair();if(context().key===ticket.key&&context().nonce===ticket.nonce&&String(last.mes||'')!==beforeText)completed=true;}finally{guard.stop();restoreDraft();clear();c.eventSource.removeListener(c.eventTypes.CHAT_CHANGED,changed);working=false;cacheStamp='';refresh();}if(completed)await apply({type:'narrated'});else throw Error(t('AI ยังไม่ส่งคำตอบ ตรวจการเชื่อมต่อแล้วลองบรรยายอีกครั้ง ผลการเล่นยังถูกเก็บไว้','No AI response received. Check the connection and retry; your progress is saved.'));}
 async function handle(b){if(await transformations.handle(b)||await release.handle(b)||await expansion.handle(b)||await shop.handle(b))return;const action=b.dataset.pkAction;if(['close','dock','hide-dock','minimize','open','nav'].includes(action)){if(action==='close'){root.close();return;}if(action==='hide-dock'){dockVisible=false;dock?.remove('pokemon');return;}if(action==='minimize'){dock?.minimize('pokemon');return;}if(action==='dock'){dockVisible=true;renderDock();dock?.select('pokemon');root.close();return;}if(action==='nav'){view=b.dataset.view;notice='';selectedUid='';render();root.querySelector('.pk-main').scrollTop=0;return;}open(b.dataset.view||'adventure');return;}
  if(action==='battle-power'){const found=transformationOptions(game,dex,game.pokemon[game.battle?.activeUid]).find(v=>v.kind===b.dataset.kind&&v.key===b.dataset.key&&v.ready);if(found)pendingTransform=pendingTransform?.kind===found.kind&&pendingTransform?.key===found.key?null:found;render();return;}
  if(action==='battle-menu'){doublePicks=[];doublePending=null;battlePane=b.dataset.pane;if(battlePane!=='moves')pendingTransform=null;render();return;}
  if(action==='dex-filters'){dexFilters=!dexFilters;render();return;}
  if(action==='dex-mode'){showForms=b.dataset.forms==='true';dexPage=0;render();return;}
  if(action==='filter-generation'){generation=Number(b.dataset.generation);dexPage=0;render();return;}
  if(action==='clear-filters'){type='';generation=0;dexPage=0;render();return;}
  if(action==='edit-nickname'){nicknameEditing=!nicknameEditing;render();root.querySelector('[name=nickname]')?.focus();return;}
  if(action==='potion-picker'){potionPicker=!potionPicker;render();root.querySelector('.pk-potion-picker')?.scrollIntoView({block:'nearest'});return;}
  if(action==='starter-region'){region=b.dataset.region;render();return;}
  if(action==='choose-starter'){await apply({type:'starter',speciesId:Number(b.dataset.species),region});view='adventure';render();return;}
  if(action==='dex-detail'||action==='mon-detail'){if(view!=='detail')previousView=view;selectedUid=action==='mon-detail'?b.dataset.uid:'';nicknameEditing=false;selected=selectedUid?game.pokemon[selectedUid].key:b.dataset.key;view='detail';render();root.querySelector('.pk-main').scrollTop=0;return;}
  if(action==='filter-type'){type=b.dataset.type;dexPage=0;render();return;}if(action==='toggle-forms'){showForms=!showForms;dexPage=0;render();return;}if(action==='dex-page'){dexPage=Number(b.dataset.page);render();root.querySelector('.pk-main').scrollTop=0;return;}
  if(action==='choose-medicine'){medicine=b.dataset.item;view=game.battle?'battle-medicine':'bag';render();return;}if(action==='bag-catalogue'){bagCatalogue=!bagCatalogue;bagPage=0;render();return;}if(action==='bag-page'){bagPage=Math.max(0,bagPage+Number(b.dataset.step));render();return;}if(action==='preset-save'){const field=root.querySelector('[data-pk-preset-name]'),name=field?.value.trim().slice(0,24);if(!name){field?.focus();return;}await apply({type:'preset-save',name,uids:[...game.party]});return;}if(action==='preset-use'){const preset=(game.presets||[]).find(v=>v.name===b.dataset.name);if(preset)await apply({type:'party-set',name:preset.name,uids:preset.uids});return;}if(action==='preset-delete'){await apply({type:'preset-delete',name:b.dataset.name});return;}if(action==='dex-progress'){dexProgress=!dexProgress;render();return;}if(action==='summary-dismiss'){battleSummary=null;render();return;}if(game?.battle?.double&&['attack','double-target'].includes(action)){const fight=game.battle,alive=[fight.wild,fight.double.foe].map(f=>f?.hp>0);
  if(action==='attack'){const moveId=Number(b.dataset.move);if(alive[0]&&alive[1]){doublePending=moveId;render();return;}doublePicks.push({moveId,target:alive[0]?0:1});}
  else{doublePicks.push({moveId:doublePending,target:Number(b.dataset.target)});doublePending=null;}
  if(doublePicks.length>=2||!(game.pokemon[fight.double.allyUid]?.hp>0)){const moves=[...doublePicks].map(v=>v||{});while(moves.length<2)moves.push({});doublePicks=[];await apply({type:'attack',moves});battlePane='commands';}
  render();return;}
 if(action==='double-back'){if(doublePending!==null)doublePending=null;else{doublePicks.pop();while(doublePicks.length&&doublePicks.at(-1)===null)doublePicks.pop();}render();return;}
 if(action==='double-slot'){doubleSlot=Number(b.dataset.slot)||0;render();return;}
 if(action==='storage-pick'){storagePick=storagePick===b.dataset.uid?'':b.dataset.uid||'';render();return;}if(action==='storage-box'){storageBox=Math.max(0,storageBox+Number(b.dataset.step));storagePick='';render();return;}if(action==='bag-pocket'){bagPocket=b.dataset.pocket||'all';bagPage=0;render();root.querySelector('.pk-pocket[aria-selected=true]')?.scrollIntoView?.({block:'nearest',inline:'center'});return;}
  if(action==='haptics-toggle'||action==='scheme-set'||action==='theme-set'||action==='sound-toggle'||action==='sound-mix-toggle'||action==='dex-image-set'){if(mutating||working||busy())return;const ticket=context();mutating=true;try{await api.savePokemonConfiguration(action==='haptics-toggle'?{haptics:game.settings.haptics===false}:action==='scheme-set'?{scheme:b.dataset.scheme}:action==='theme-set'?{theme:b.dataset.theme}:action==='dex-image-set'?{dexImageMode:b.dataset.mode,...game.settings.spriteStyle?{spriteStyle:''}:{}}:action==='sound-mix-toggle'?{soundMix:game.settings.soundMix===false}:{sound:game.settings.sound===false});assertScope(ticket);}finally{mutating=false;refresh();}return;}if(action==='narrate'){await narrate();return;}if(action==='motion-toggle'){if(mutating||working||busy())return;const ticket=context(),value=game.settings.motion===false;mutating=true;render();try{await api.savePokemonConfiguration({motion:value});assertScope(ticket);}finally{mutating=false;refresh();}return;}if(action==='auto-narrate'){await apply({type:'settings',autoNarrate:!game.settings.autoNarrate});return;}if(action==='player-encounters'){await apply({type:'settings',playerEncounters:!game.settings.playerEncounters});return;}if(action==='set-region'){await apply({type:'settings',region:b.dataset.region});return;}
  const event={type:action};if(action==='attack'&&pendingTransform)event.transform={kind:pendingTransform.kind,key:pendingTransform.key};if(b.dataset.uid)event.uid=b.dataset.uid;if(b.dataset.move)event.moveId=Number(b.dataset.move);if(b.dataset.ball)event.ball=b.dataset.ball;if(b.dataset.to)event.to=Number(b.dataset.to);if(b.dataset.slot)event.slot=Number(b.dataset.slot);await apply(event);if(['attack','switch','run','forfeit'].includes(action))pendingTransform=null;if(['deposit','withdraw'].includes(action)&&view==='storage')storagePick='';if(['attack','potion','catch','switch','run'].includes(action))battlePane='commands';if(action==='switch')view='adventure';if(action==='potion')potionPicker=false;if(['evolve','trade-evolve'].includes(action)&&selectedUid)selected=game.pokemon[selectedUid].key;render();
 }
 root.addEventListener('submit',e=>{if(transformations.submit(e)||release.submit(e))return;if(e.target.matches('[data-pk-use-item]')){e.preventDefault();const f=new FormData(e.target);void apply({type:'use-item',item:medicine,uid:f.get('uid'),moveId:Number(f.get('moveId'))}).then(()=>{medicine='';battlePane='commands';view=game.battle?'adventure':'bag';render();}).catch(showError);return;}try{if(expansion.submit(e))return;}catch(error){showError(error);return;}if(!e.target.matches('[data-pk-nickname]'))return;e.preventDefault();const name=new FormData(e.target).get('nickname');void apply({type:'nickname',uid:selectedUid,name}).then(()=>{nicknameEditing=false;render();}).catch(showError);});
 const menuSound=createPokemonMenuSound({url:new URL('assets/menu-confirm-v2.wav',import.meta.url).href});const clicked=e=>{const b=e.target.closest('[data-pk-action]');if(b&&!b.disabled&&!motion.playing()){if(game?.settings.sound!==false){if(b.dataset.pkAction==='sound-mix-toggle'&&game.settings.soundMix===false)menuSound.configure({mix:true});menuSound.play();}void handle(b).catch(showError);}};function artError(e){const img=e.target;if(!img.matches?.('img:not(.pk-battle-sprite)')||img.dataset.failed)return;
  if(img.matches('.pk-pokemon-sprite')){failedSprites.add(img.src);const p=dex.get(img.dataset.pkArtKey),m={shiny:img.dataset.pkShiny==='1',traits:{gender:img.dataset.pkGender}},next=portraitSprites(p,m,img.dataset.pkList==='1')[0];if(next){img.dataset.pkAnimated=String(next.animated);img.classList.toggle('pk-style-hd',Boolean(next.family&&next.family!=='pixel'));img.classList.toggle('pk-sprite-idle',spriteMotion()&&!next.animated);img.src=next.url;return;}const artwork=imageUrl(p,m);if(artwork&&artwork!==img.src&&!failedSprites.has(artwork)){img.classList.remove('pk-pokemon-sprite','pk-sprite-idle');img.dataset.pkArtFallback='true';img.src=artwork;return;}}
  else if(img.dataset.pkArtKey&&!img.dataset.pkArtFallback){const url=frontStill(dex.get(img.dataset.pkArtKey),{shiny:img.dataset.pkShiny==='1',traits:{gender:img.dataset.pkGender}});if(url&&url!==img.src){img.dataset.pkArtFallback='true';img.src=url;return;}}
  img.dataset.failed='true';const fallback=document.createElement('span');fallback.className='pk-art-missing';fallback.setAttribute('role','img');fallback.setAttribute('aria-label',img.alt||t('ภาพไม่พร้อมใช้งาน','Artwork unavailable'));fallback.innerHTML=fa('paw');img.replaceWith(fallback);
 }root.addEventListener('error',artError,true);panel.addEventListener('error',artError,true);root.addEventListener('click',clicked);panel.addEventListener('click',clicked);
 root.addEventListener('input',e=>{if(e.target.matches('[data-pk-volume]')){const value=Math.max(0,Math.min(100,Number(e.target.value)));e.target.style.setProperty('--pk-volume',value+'%');e.target.nextElementSibling.value=value+'%';menuSound.configure({volume:game.settings.sound===false?0:value/100});return;}if(expansion.input(e))return;if(e.target.matches('[data-pk-bag-search]')){bagSearch=e.target.value;bagPage=0;const caret=e.target.selectionStart;render();const n=root.querySelector('[data-pk-bag-search]');n?.focus({preventScroll:true});n?.setSelectionRange(caret,caret);return;}if(e.target.matches('[data-pk-search]')){query=e.target.value;dexPage=0;clearTimeout(searchTimer);if(!searchComposing&&!e.isComposing)searchTimer=setTimeout(updateDexSearch,90);}});

 root.addEventListener('compositionstart',e=>{if(e.target.matches('[data-pk-search]')){searchComposing=true;clearTimeout(searchTimer);}});
