 const subscriptions=[],host=cHost();for(const event of [...new Set([host.eventTypes.CHAT_CHANGED,host.eventTypes.MESSAGE_SENT,host.eventTypes.USER_MESSAGE_RENDERED,host.eventTypes.MESSAGE_RECEIVED,host.eventTypes.MESSAGE_UPDATED,host.eventTypes.MESSAGE_EDITED,host.eventTypes.MESSAGE_SWIPED,host.eventTypes.MESSAGE_DELETED].filter(Boolean))]){const fn=(...args)=>{if(event===host.eventTypes.MESSAGE_RECEIVED)markLive(...args);const before=game,oldScope=scope,oldNonce=nonce;if(event!==host.eventTypes.MESSAGE_RECEIVED)motion.cancel();refresh();if(event===host.eventTypes.MESSAGE_RECEIVED&&!mutating&&oldScope===scope&&oldNonce===nonce&&before&&!before.battle&&game?.battle){presentNewBattle(before);playMotion(motionSequence(before,game,{type:'story-encounter'},dex),game);}};host.eventSource.on(event,fn);subscriptions.push([event,fn]);}
 const language=e=>{if(e.target?.id==='tretaresia-rpg-language')render();};document.addEventListener('change',language);window.addEventListener('resize',viewport);visualViewport?.addEventListener('resize',viewport);viewport();
